{"code": "import tensorflow as tf
import numpy as np

GCS_PATH = "data/tfrecords-jpeg-192x192"
TRAINING_FILENAMES = tf.io.gfile.glob(GCS_PATH + '/train/*.tfrec')

print(f"Found {len(TRAINING_FILENAMES)} training files")
print(f"First few files: {TRAINING_FILENAMES[:3]}")

# Try to read the first record from the first file
def count_data_items(filenames):
    import re
    n = [int(re.compile(r"-([0-9]*)\.").search(filename).group(1)) for filename in filenames]
    return np.sum(n)

try:
    NUM_TRAINING_IMAGES = count_data_items(TRAINING_FILENAMES)
    print(f"Expected number of images: {NUM_TRAINING_IMAGES}")
except Exception as e:
    print(f"Error counting items: {e}")

# Try to read a single record from the first file
try:
    raw_dataset = tf.data.TFRecordDataset(TRAINING_FILENAMES[0])
    for raw_record in raw_dataset.take(1):
        print("Successfully read first record, size:", len(raw_record.numpy()))
except Exception as e:
    print(f"Error reading record: {e}")"}

